import{_ as o,a0 as i,w as c,s as r,ao as d,I as n,x as a,a1 as s,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 上使用 Glances 监控系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上使用 Glances 监控系统 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上使用 Glances 监控系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上使用 Glances 监控系统 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151223 How to Use Glances to Monitor System on Ubuntu","title":"如何在 Ubuntu 上使用 Glances 监控系统","tag":"201601","desc":""},"relativePath":"201601/20151223 How to Use Glances to Monitor System on Ubuntu.md","filePath":"[post].md"}'),p={name:"201601/20151223 How to Use Glances to Monitor System on Ubuntu.md"};function u(m,e,h,g,G,b){const l=i("Link");return c(),r("div",null,[e[13]||(e[13]=d(`<h1 id="如何在-ubuntu-上使用-glances-监控系统" tabindex="-1">如何在 Ubuntu 上使用 Glances 监控系统 <a class="header-anchor" href="#如何在-ubuntu-上使用-glances-监控系统" aria-label="Permalink to “如何在 Ubuntu 上使用 Glances 监控系统”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/glances_featured.jpg" alt=""></p><p>Glances 是一个用于监控系统的跨平台、基于文本模式的命令行工具。它是用 Python 编写的，使用 <code>psutil</code> 库从系统获取信息。你可以用它来监控 CPU、平均负载、内存、网络接口、磁盘 I/O，文件系统空间利用率、挂载的设备、所有活动进程以及消耗资源最多的进程。Glances 有很多有趣的选项。它的主要特性之一是可以在配置文件中设置阀值（careful[小心]、warning[警告]、critical[致命]），然后它会用不同颜色显示信息以表明系统的瓶颈。</p><h3 id="glances-的功能" tabindex="-1">Glances 的功能 <a class="header-anchor" href="#glances-的功能" aria-label="Permalink to “Glances 的功能”">​</a></h3><ul><li>CPU 平均负载</li><li>不同状态（如活动、休眠）进程的数量</li><li>所有内存信息，如物理内存、交换空间、空闲内存</li><li>CPU 信息</li><li>网络连接的上行/下行速度</li><li>磁盘 I/O 读/写速度详细信息</li><li>当前挂载设备的磁盘使用情况</li><li>消耗资源最多的进程和他们的 CPU/内存使用情况</li></ul><h3 id="安装-glances" tabindex="-1">安装 Glances <a class="header-anchor" href="#安装-glances" aria-label="Permalink to “安装 Glances”">​</a></h3><p>Glances 在 Ubuntu 的软件仓库中，所以安装很简单。执行下面的命令安装 Glances：</p><pre><code>sudo apt-get install glances
</code></pre><p>（LCTT 译注：若安装后无法正常使用，可考虑使用 pip 安装/升级 glances：<code>sudo pip install --upgrade glances</code>）</p><h3 id="glances-使用方法" tabindex="-1">Glances 使用方法 <a class="header-anchor" href="#glances-使用方法" aria-label="Permalink to “Glances 使用方法”">​</a></h3><p>安装完成后，可以执行下面的命令启动 Glances：</p><pre><code>glances
</code></pre><p>你将看到类似下图的输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/glances_output1.png" alt="glances monitor system output"></p><p>要退出 Glances 终端，按 ESC 键或 <code>Ctrl + C</code>。</p><p>默认情况下，时间间隔（LCTT 译注：显示数据刷新的时间间隔）是 1s，不过你可以在从终端启动 Glances 时自定义时间间隔。</p><p>要把时间间隔设为 5s，执行下面的命令：</p><pre><code>glances -t 5
</code></pre><h3 id="glances-中不同颜色含义" tabindex="-1">Glances 中不同颜色含义 <a class="header-anchor" href="#glances-中不同颜色含义" aria-label="Permalink to “Glances 中不同颜色含义”">​</a></h3><p>Glances 中不同颜色的含义：</p><ul><li><code>绿色</code>：正常（OK）</li><li><code>蓝色</code>：小心（careful）</li><li><code>紫色</code>：警告（warning）</li><li><code>红色</code>：致命（critical）</li></ul><p>默认设置下，Glances 的阀值设置是：careful=50，warning=70，critical=90。你可以通过 “/etc/glances/” 目录下的默认配置文件 glances.conf 来自定义这些阀值。</p><h3 id="glances-的选项" tabindex="-1">Glances 的选项 <a class="header-anchor" href="#glances-的选项" aria-label="Permalink to “Glances 的选项”">​</a></h3><p>Glances 提供了很多快捷键，可以在它运行时用来查找输出信息。</p><p>下面是一些常用的热键列表：</p><ul><li><code>m</code> : 按内存占用排序进程</li><li><code>p</code> : 按进程名称排序进程</li><li><code>c</code> : 按 CPU 占用率排序进程</li><li><code>i</code> : 按 I/O 频率排序进程</li><li><code>a</code> : 自动排序进程</li><li><code>d</code> : 显示/隐藏磁盘 I/O 统计信息</li><li><code>f</code> : 显示/隐藏文件系统统计信息</li><li><code>s</code> : 显示/隐藏传感器统计信息</li><li><code>y</code> : 显示/隐藏硬盘温度统计信息</li><li><code>l</code> : 显示/隐藏日志</li><li><code>n</code> : 显示/隐藏网络统计信息</li><li><code>x</code> : 删除警告和严重日志</li><li><code>h</code> : 显示/隐藏帮助界面</li><li><code>q</code> : 退出</li><li><code>w</code> : 删除警告记录</li></ul><h3 id="使用-glances-监控远程系统" tabindex="-1">使用 Glances 监控远程系统 <a class="header-anchor" href="#使用-glances-监控远程系统" aria-label="Permalink to “使用 Glances 监控远程系统”">​</a></h3><p>你也可以使用 Glances 监控远程系统。要在远程系统上使用它，使用下面的命令：</p><pre><code>glances -s
</code></pre><p>你会看到类似下面的输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/glances_server.png" alt="glances monitor remote system server"></p><p>如你所见，Glances 运行在 61209 端口。</p><p>现在，到远程机器上执行下面的命令以连接到指定 IP 地址的 Glances 服务器上。假设 192.168.1.10 是你的 Glances 服务器 IP 地址。</p><pre><code>glances -c -P 192.168.1.10
</code></pre><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>对于每个 Linux 系统管理员来说，Glances 都是一个非常有用的工具。使用它，你可以轻松、高效地监控 Linux 系统。如果你有什么问题，自由地评论吧。</p><hr>`,37)),n("p",null,[e[1]||(e[1]=a("via: ",-1)),s(l,{href:"https://www.maketecheasier.com/glances-monitor-system-ubuntu/"},{default:t(()=>[...e[0]||(e[0]=[a("https://www.maketecheasier.com/glances-monitor-system-ubuntu/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=a("作者：",-1)),s(l,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:t(()=>[...e[2]||(e[2]=[a("Hitesh Jethva",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),s(l,{href:"https://github.com/bianjp"},{default:t(()=>[...e[3]||(e[3]=[a("bianjp",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),s(l,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=a("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创编译，",-1)),s(l,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const C=o(p,[["render",u]]);export{T as __pageData,C as default};
